import json, pathlib
from IPython.display import HTML, display

Sig_demo = np.array([[9.0, 7.2], [7.2, 16.0]])
mu_demo = np.array([50.0, 120.0])
cloud = rng.multivariate_normal(mu_demo, Sig_demo, size=400)
focus = np.array([54.0, 116.0])          # the observation we track

L = np.linalg.cholesky(Sig_demo)
d_raw = focus - mu_demo

payload = {
    "pts":   np.round(cloud - mu_demo, 3).tolist(),   # centred cloud
    "focus": np.round(d_raw, 6).tolist(),
    "mu":    mu_demo.tolist(),
    "L":     L.tolist(),
    "Linv":  np.linalg.inv(L).tolist(),
    "Dval":  float(np.sqrt(d_raw @ np.linalg.solve(Sig_demo, d_raw))),
    # The grid and its labels carry the first half of the slider on their own
    # — centring only changes the numbers — so they are drawn stronger here
    # than in the static figures, where they are just background.
    "colors": {"grey": C["grey"], "red": C["red"], "dark": C["dark"],
               "grid": "#ccd4db", "axis": "#9aa4ad", "tick": "#3f4850"},
}

js = pathlib.Path("whitening-widget.js").read_text(encoding="utf-8")
js = js.replace("__ID__", "mw-whiten").replace("__DATA__", json.dumps(payload))

